/**
 * Model UsageRecord
 * One row per (organization, metric, billing period). Incremented after work
 * succeeds, so a failed crawl or a failed LLM call never burns the customer's
 * allowance.
 */
export type UsageRecord = $Result.DefaultSelection<Prisma.$UsageRecordPayload>
/**
 * Model TrackedPrompt
 * A question we ask AI assistants on a schedule to see whether they cite the
 * customer. This is the unit the AI Visibility dashboard is built on.
 */
export type TrackedPrompt = $Result.DefaultSelection<Prisma.$TrackedPromptPayload>
/**
 * Model PromptCheck
 * One run of one prompt against one assistant.
 */
export type PromptCheck = $Result.DefaultSelection<Prisma.$PromptCheckPayload>
/**
 * Model SiteRepository
 * How a client's website code is reached, so fixes and new content can be
 * written back to it.
 */
export type SiteRepository = $Result.DefaultSelection<Prisma.$SiteRepositoryPayload>
/**
 * Model AutomationRun
 * One end-to-end pass: clone, patch and/or write content, validate, open a PR.
 */
export type AutomationRun = $Result.DefaultSelection<Prisma.$AutomationRunPayload>
/**
 * Model ContentPiece
 * A page the strategy said to add, tracked from plan through to live.
 */
export type ContentPiece = $Result.DefaultSelection<Prisma.$ContentPiecePayload>
/**
 * Model StrategyReport
 * A generated go-to-market plan: market read, SEO roadmap, content plan, and
 * social strategy, grounded in this project's crawl and visibility evidence.
 */
export type StrategyReport = $Result.DefaultSelection<Prisma.$StrategyReportPayload>
/**
 * Model CompetitorDomain
 * A rival the customer wants share-of-voice measured against.
 */
export type CompetitorDomain = $Result.DefaultSelection<Prisma.$CompetitorDomainPayload>
/**
 * Model WebhookEvent
 * Razorpay retries webhooks aggressively. Storing the delivery id makes
 * handling idempotent so a retried `subscription.charged` cannot roll the
 * billing period forward twice.
 */
export type WebhookEvent = $Result.DefaultSelection<Prisma.$WebhookEventPayload>
/**
 * Model AuditLog
 * 
 */
export type AuditLog = $Result.DefaultSelection<Prisma.$AuditLogPayload>
/**
 * Model LocalLocation
 * 
 */
export type LocalLocation = $Result.DefaultSelection<Prisma.$LocalLocationPayload>

